{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C28"],
      "claim": "Acamprosate, a small polar ionized molecule, has absolute oral bioavailability of only 11 ± 1% in healthy volunteers after oral tablet administration versus IV, supporting low F for highly polar ionized compounds.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C14"],
      "claim": "Ferulic acid, a polar phenolic acid, shows only 3–10% oral bioavailability in humans, supporting low oral bioavailability for polar acidic molecules.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C23"],
      "claim": "Tegaserod has an absolute oral bioavailability of approximately 10% in healthy volunteers, providing another example of a small molecule with F well below the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C29"],
      "claim": "Oseltamivir carboxylate, a polar ionized carboxylic acid metabolite, has poor oral bioavailability (<5%) when administered directly, directly supporting low F for ionized carboxylic acid-containing molecules.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C22"],
      "claim": "Oseltamivir carboxylate can reach about 80% absolute bioavailability, but only after oral administration of the prodrug oseltamivir; this reflects prodrug absorption and conversion, not direct permeability of the polar carboxylate.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is a highly polar, fully ionized dicarboxylic acid with very low predicted passive permeability. Direct experimental analogues—acamprosate (11%), ferulic acid (3–10%), tegaserod (~10%), and oseltamivir carboxylate (<5% direct)—all fall below the 20% threshold. The only high-bioavailability carboxylate example requires prodrug administration, which does not apply to the query. Therefore the prediction is low oral bioavailability.",
  "evidence_gaps": [
    "No direct experimental bioavailability data are available for the query molecule.",
    "No data address possible active transport, efflux, or formulation effects for the query.",
    "The cyclic peptide-like structure may have atypical permeability behavior not fully captured by the small-molecule analogues."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

